    DeletePerformanceAnalysisReportRequest.add_member(:identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentifierString, location_name: 'Identifier', traits: {"smithy.api#documentation" => "<p>An immutable identifier for a data source that is unique for an Amazon Web Services Region. Performance Insights gathers metrics from this data source. \n            In the console, the identifier is shown as <i>ResourceID</i>. When you \n            call <code>DescribeDBInstances</code>, the identifier is returned as <code>DbiResourceId</code>.</p>\n         <p>To use a DB instance as a data source, specify its <code>DbiResourceId</code> value. For example, specify\n            <code>db-ABCDEFGHIJKLMNOPQRSTU1VW2X</code>.</p>", "smithy.api#required" => {}}))
    DeletePerformanceAnalysisReportRequest.add_member(:analysis_report_id, Smithy::Schema::Shapes::ShapeRef.new(shape: AnalysisReportId, location_name: 'AnalysisReportId', traits: {"smithy.api#documentation" => "<p>The unique identifier of the analysis report for deletion.</p>", "smithy.api#required" => {}}))
    DeletePerformanceAnalysisReportRequest.type = Types::DeletePerformanceAnalysisReportRequest
    DeletePerformanceAnalysisReportResponse.type = Types::DeletePerformanceAnalysisReportResponse
    DescribeDimensionKeysRequest.add_member(:service_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceType, location_name: 'ServiceType', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services service for which Performance Insights will return metrics. Valid values are as follows:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>RDS</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>DOCDB</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentifierString, location_name: 'Identifier', traits: {"smithy.api#documentation" => "<p>An immutable, Amazon Web Services Region-unique identifier for a data source. Performance Insights gathers metrics from\n            this data source.</p>\n         <p>To use an Amazon RDS instance as a data source, you specify its <code>DbiResourceId</code> value. \n            For example, specify <code>db-FAIHNTYBKTGAUSUZQYPDS2GW4A</code>.\n        </p>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ISOTimestamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time specifying the beginning of the requested time series data. You must specify a\n            <code>StartTime</code> within the past 7 days. The value specified is <i>inclusive</i>, \n            which means that data points equal to or greater than <code>StartTime</code> are returned.\n        </p>\n         <p>The value for <code>StartTime</code> must be earlier than the value for <code>EndTime</code>.\n        </p>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ISOTimestamp, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The date and time specifying the end of the requested time series data. The value specified is\n      <i>exclusive</i>, which means that data points less than (but not equal to) <code>EndTime</code> are\n      returned.</p>\n         <p>The value for <code>EndTime</code> must be later than the value for <code>StartTime</code>.</p>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:metric, Smithy::Schema::Shapes::ShapeRef.new(shape: RequestString, location_name: 'Metric', traits: {"smithy.api#documentation" => "<p>The name of a Performance Insights metric to be measured.</p>\n         <p>Valid values for <code>Metric</code> are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db.load.avg</code> - A scaled representation of the number of active sessions for the database engine. </p>\n            </li>\n            <li>\n               <p>\n                  <code>db.sampledload.avg</code> - The raw number of active sessions for the database engine. </p>\n            </li>\n         </ul>\n         <p>If the number of active sessions is less than an internal Performance Insights threshold, <code>db.load.avg</code> \n            and <code>db.sampledload.avg</code> are the same value. If the number of active sessions is greater than \n            the internal threshold, Performance Insights samples the active sessions, with <code>db.load.avg</code> \n            showing the scaled values, <code>db.sampledload.avg</code> showing the raw values, and \n            <code>db.sampledload.avg</code> less than <code>db.load.avg</code>. For most use cases, you can \n            query <code>db.load.avg</code> only.\n        </p>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:period_in_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'PeriodInSeconds', traits: {"smithy.api#documentation" => "<p>The granularity, in seconds, of the data points returned from Performance Insights. A period can be as short as \n            one second, or as long as one day (86400 seconds). Valid values are:\n        </p>\n         <ul>\n            <li>\n               <p>\n                  <code>1</code> (one second)</p>\n            </li>\n            <li>\n               <p>\n                  <code>60</code> (one minute)</p>\n            </li>\n            <li>\n               <p>\n                  <code>300</code> (five minutes)</p>\n            </li>\n            <li>\n               <p>\n                  <code>3600</code> (one hour)</p>\n            </li>\n            <li>\n               <p>\n                  <code>86400</code> (twenty-four hours)</p>\n            </li>\n         </ul>\n         <p>If you don't specify <code>PeriodInSeconds</code>, then Performance Insights chooses a value for you, with a \n            goal of returning roughly 100-200 data points in the response.\n        </p>"}))
    DescribeDimensionKeysRequest.add_member(:group_by, Smithy::Schema::Shapes::ShapeRef.new(shape: DimensionGroup, location_name: 'GroupBy', traits: {"smithy.api#documentation" => "<p>A specification for how to aggregate the data points from a query result. You must specify a valid dimension group. Performance Insights returns all\n            dimensions within this group, unless you provide the names of specific dimensions within this group. You can also request that Performance Insights return\n            a limited number of values for a dimension. </p>", "smithy.api#required" => {}}))
    DescribeDimensionKeysRequest.add_member(:additional_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: AdditionalMetricsList, location_name: 'AdditionalMetrics', traits: {"smithy.api#documentation" => "<p>Additional metrics for the top <code>N</code> dimension keys. If the specified dimension group in the <code>GroupBy</code> parameter is\n                <code>db.sql_tokenized</code>, you can specify per-SQL metrics to get the values for the top <code>N</code> SQL digests. The response\n            syntax is as follows: <code>\"AdditionalMetrics\" : { \"<i>string</i>\" : \"<i>string</i>\" }</code>.</p>\n         <p>The only supported statistic function is <code>.avg</code>.</p>"}))
    DescribeDimensionKeysRequest.add_member(:partition_by, Smithy::Schema::Shapes::ShapeRef.new(shape: DimensionGroup, location_name: 'PartitionBy', traits: {"smithy.api#documentation" => "<p>For each dimension specified in <code>GroupBy</code>, specify a secondary dimension \n            to further subdivide the partition keys in the response.\n        </p>"}))
    DescribeDimensionKeysRequest.add_member(:filter, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricQueryFilterMap, location_name: 'Filter', traits: {"smithy.api#documentation" => "<p>One or more filters to apply in the request. Restrictions:</p>\n         <ul>\n            <li>\n               <p>Any number of filters by the same dimension, as specified in the <code>GroupBy</code> or\n          <code>Partition</code> parameters.</p>\n            </li>\n            <li>\n               <p>A single filter for any other dimension in this dimension group.</p>\n            </li>\n         </ul>\n         <note>\n            <p>The <code>db.sql.db_id</code> filter isn't available for RDS for SQL Server DB instances.</p>\n         </note>"}))
    DescribeDimensionKeysRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxResults, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of items to return in the response. If more items exist than the specified <code>MaxRecords</code> value, a\n            pagination token is included in the response so that the remaining results can be retrieved. </p>"}))
    DescribeDimensionKeysRequest.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>An optional pagination token provided by a previous request. If this parameter is specified, the response includes only records beyond\n            the token, up to the value specified by <code>MaxRecords</code>.</p>"}))
    DescribeDimensionKeysRequest.type = Types::DescribeDimensionKeysRequest
    DescribeDimensionKeysResponse.add_member(:aligned_start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ISOTimestamp, location_name: 'AlignedStartTime', traits: {"smithy.api#documentation" => "<p>The start time for the returned dimension keys, after alignment to a granular boundary (as specified by <code>PeriodInSeconds</code>).\n            <code>AlignedStartTime</code> will be less than or equal to the value of the user-specified <code>StartTime</code>. </p>"}))
    DescribeDimensionKeysResponse.add_member(:aligned_end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ISOTimestamp, location_name: 'AlignedEndTime', traits: {"smithy.api#documentation" => "<p>The end time for the returned dimension keys, after alignment to a granular boundary (as specified by <code>PeriodInSeconds</code>).\n            <code>AlignedEndTime</code> will be greater than or equal to the value of the user-specified <code>Endtime</code>. </p>"}))
    DescribeDimensionKeysResponse.add_member(:partition_keys, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponsePartitionKeyList, location_name: 'PartitionKeys', traits: {"smithy.api#documentation" => "<p>If <code>PartitionBy</code> was present in the request, <code>PartitionKeys</code> contains the breakdown of dimension keys by the\n            specified partitions. </p>"}))
    DescribeDimensionKeysResponse.add_member(:keys, Smithy::Schema::Shapes::ShapeRef.new(shape: DimensionKeyDescriptionList, location_name: 'Keys', traits: {"smithy.api#documentation" => "<p>The dimension keys that were requested.</p>"}))
    DescribeDimensionKeysResponse.add_member(:next_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextToken, location_name: 'NextToken', traits: {"smithy.api#documentation" => "<p>A pagination token that indicates the response didn’t return all available records because <code>MaxRecords</code> was specified in the\n            previous request. To get the remaining records, specify <code>NextToken</code> in a separate request with this value. </p>"}))
    DescribeDimensionKeysResponse.type = Types::DescribeDimensionKeysResponse
