    DimensionKeyDescription.add_member(:total, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Total', traits: {"smithy.api#documentation" => "<p>The aggregated metric value for the dimensions, over the requested time range.</p>"}))
    DimensionKeyDescription.add_member(:additional_metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: AdditionalMetricsMap, location_name: 'AdditionalMetrics', traits: {"smithy.api#documentation" => "<p>A map that contains the value for each additional metric.</p>"}))
