    DimensionKeyDetail.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>The value of the dimension detail data. Depending on the return status, this value is either the \n          full or truncated SQL query for the following dimensions:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db.query.statement</code> (Amazon DocumentDB)</p>\n            </li>\n            <li>\n               <p>\n                  <code>db.sql.statement</code> (Amazon RDS and Aurora)</p>\n            </li>\n         </ul>"}))
    DimensionKeyDetail.add_member(:dimension, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Dimension', traits: {"smithy.api#documentation" => "<p>The full name of the dimension. The full name includes the group name and key name. The following values are valid:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>db.query.statement</code> (Amazon DocumentDB)</p>\n            </li>\n            <li>\n               <p>\n                  <code>db.sql.statement</code> (Amazon RDS and Aurora)</p>\n            </li>\n         </ul>"}))
    DimensionKeyDetail.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: DetailStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The status of the dimension detail data. Possible values include the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AVAILABLE</code> - The dimension detail data is ready to be retrieved.</p>\n            </li>\n            <li>\n               <p>\n                  <code>PROCESSING</code> - The dimension detail data isn't ready to be retrieved because more processing time is required. If the\n                    requested detail data has the status <code>PROCESSING</code>, Performance Insights returns the truncated query.</p>\n            </li>\n            <li>\n               <p>\n                  <code>UNAVAILABLE</code> - The dimension detail data could not be collected successfully.</p>\n            </li>\n         </ul>"}))
