    GetResourceMetricsRequest.add_member(:metric_queries, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricQueryList, location_name: 'MetricQueries', traits: {"smithy.api#documentation" => "<p>An array of one or more queries to perform. Each query must specify a Performance Insights metric and specify an aggregate function, and you can provide filtering\n            criteria. You must append the aggregate function to the metric. For example, to find the average for the metric <code>db.load</code> \n            you must use <code>db.load.avg</code>. Valid values for aggregate functions include <code>.avg</code>, <code>.min</code>, \n            <code>.max</code>, and <code>.sum</code>.</p>", "smithy.api#required" => {}}))
    GetResourceMetricsRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: ISOTimestamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time specifying the beginning of the requested time series query range. You can't\n            specify a <code>StartTime</code> that is earlier than 7 days ago. By default, Performance Insights has 7 days of \n            retention, but you can extend this range up to 2 years. The value specified is\n            <i>inclusive</i>. Thus, the command returns data points equal to or greater \n            than <code>StartTime</code>.</p>\n         <p>The value for <code>StartTime</code> must be earlier than the value for <code>EndTime</code>.</p>", "smithy.api#required" => {}}))
